> +	TAS2557_GPIO5_PIN_REG,            0x01,	/* GPIO5 = ASI2 BCLK input */

This looks awfully board specific....

> +static int tas2557_dev_bulk_write(struct tas2557_priv *tas2557, unsigned int chn,
