+void knod_free_mem(struct knod *knod, struct knod_mem *mem)
+{
+	if (mem) {
+		list_del_init(&mem->list);
+		kfd_process_free_gpuvm(mem->mem, knod->process->pdds[0],
+				       &mem->kaddr);
+		gen_pool_free(knod->pool, mem->gaddr, mem->size);
+		kfree(mem);
+	}
+}
+EXPORT_SYMBOL(knod_free_mem);
